int Suche(int[] a, int g)
{
    int links = 0, rechts = a.Length - 1;
    while (links < rechts)
    {
        int mitte = (links + rechts) / 2;
        if (a[mitte] == g) return mitte;
        if (a[mitte] < g) links = mitte + 1;
        else rechts = mitte - 1;
    }
